/**
 * VORTEX PROTOCOL - Main Application Entry
 * Portfolio hygiene protocol: scan, classify, and consolidate dust
 * Base-first, risk-aware, gasless execution
 */

import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { Layout } from './src/components/layout/Layout';
import { LandingPage } from './src/pages/LandingPage';
import { ScanPage } from './src/pages/ScanPage';
import { ConsolidatePage } from './src/pages/ConsolidatePage';
import { DashboardPage } from './src/pages/DashboardPage';
import { SettingsPage } from './src/pages/SettingsPage';
import { useWallet } from './src/hooks/useWallet';
import { useTheme } from './src/hooks/useTheme';
import { useToast } from './src/hooks/useToast';
import './src/styles/index.css';

export default function App() {
  const { wallet, isConnecting, connect, disconnect } = useWallet();
  const { theme, toggleTheme } = useTheme();
  const { toasts, removeToast, success, error, warning, info } = useToast();

  const handleShowToast = (type: 'success' | 'error' | 'warning' | 'info', title: string, message?: string) => {
    switch (type) {
      case 'success':
        success(title, message);
        break;
      case 'error':
        error(title, message);
        break;
      case 'warning':
        warning(title, message);
        break;
      case 'info':
        info(title, message);
        break;
    }
  };

  return (
    <HashRouter>
      <Layout
        wallet={wallet}
        onConnect={connect}
        onDisconnect={disconnect}
        isConnecting={isConnecting}
        theme={theme}
        onToggleTheme={toggleTheme}
        toasts={toasts}
        onDismissToast={removeToast}
      >
        <Routes>
          <Route
            path="/"
            element={
              <LandingPage
                onConnectWallet={connect}
                isWalletConnected={wallet.isConnected}
              />
            }
          />
          <Route
            path="/scan"
            element={
              <ScanPage
                walletAddress={wallet.address}
                onShowToast={handleShowToast}
              />
            }
          />
          <Route
            path="/consolidate"
            element={
              <ConsolidatePage
                onShowToast={handleShowToast}
              />
            }
          />
          <Route
            path="/dashboard"
            element={
              <DashboardPage
                walletAddress={wallet.address}
              />
            }
          />
          <Route
            path="/settings"
            element={
              <SettingsPage
                onShowToast={handleShowToast}
              />
            }
          />
        </Routes>
      </Layout>
    </HashRouter>
  );
}

