/**
 * Core type definitions for VORTEX PROTOCOL
 * Includes: Chain types, Asset types, Risk classification, Wallet state, and UI state types
 */

// Chain definitions for the 11 supported chains
export type ChainId = 
  | 'solana'
  | 'base'
  | 'ethereum'
  | 'arbitrum'
  | 'optimism'
  | 'polygon'
  | 'bsc'
  | 'avalanche'
  | 'zksync'
  | 'monad'
  | 'celo';

export interface Chain {
  id: ChainId;
  name: string;
  shortName: string;
  icon: string;
  isEVM: boolean;
  color: string;
}

// Risk classification tiers
export type RiskTier = 'LEGIT' | 'DUST' | 'MICRODUST' | 'RISK_SCAM';

export interface RiskDetails {
  score: number; // 0-100
  confidence: number; // 0-100
  factors: RiskFactor[];
}

export interface RiskFactor {
  name: string;
  description: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
}

// Asset types
export type AssetType = 'token' | 'nft';

export interface Asset {
  id: string;
  name: string;
  symbol: string;
  type: AssetType;
  chainId: ChainId;
  valueUSD: number;
  balance: string;
  decimals: number;
  logoUrl?: string;
  tier: RiskTier;
  riskDetails?: RiskDetails;
  liquidity: 'high' | 'medium' | 'low' | 'none';
  contractAddress?: string;
}

// Scan results
export interface ScanResults {
  totalValueUSD: number;
