/src/hooks/useTheme.ts:
/**
 * Theme management hook for VORTEX PROTOCOL
 * Handles light/dark mode with system preference detection
 * Persists preference to localStorage
 */

import { useState, useEffect, useCallback } from 'react';

type Theme = 'light' | 'dark';

export function useTheme() {
  const [theme, setThemeState] = useState<Theme>('light');

  useEffect(() => {
    // Check localStorage first
    const stored = localStorage.getItem('vortex-theme') as Theme | null;
    if (stored) {
      setThemeState(stored);
      document.documentElement.classList.toggle('dark', stored === 'dark');
      return;
    }

    // Fall back to system preference
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const defaultTheme = prefersDark ? 'dark' : 'light';
    setThemeState(defaultTheme);
    document.documentElement.classList.toggle('dark', defaultTheme === 'dark');
  }, []);

  const setTheme = useCallback((newTheme: Theme) => {
    setThemeState(newTheme);
    localStorage.setItem('vortex-theme', newTheme);
    document.documentElement.classList.toggle('dark', newTheme === 'dark');
  }, []);

  const toggleTheme = useCallback(() => {
    setTheme(theme === 'light' ? 'dark' : 'light');
  }, [theme, setTheme]);

  return {
    theme,
    setTheme,
    toggleTheme,
    isDark: theme === 'dark',
  };
}

/src/hooks/useToast.ts:
/**
 * Toast notification hook for VORTEX PROTOCOL
 * Manages toast queue with auto-dismiss functionality
 */

import { useState, useCallback } from 'react';
import { Toast, ToastType } from '../types';

let toastId = 0;

export function useToast() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((type: ToastType, title: string, message?: string, duration = 5000) => {
    const id = `toast-${++toastId}`;
    const toast: Toast = { id, type, title, message, duration };

    setToasts(prev => [...prev, toast]);

    if (duration > 0) {
      setTimeout(() => {
        setToasts(prev => prev.filter(t => t.id !== id));
      }, duration);
    }

    return id;
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const success = useCallback((title: string, message?: string) => {
    return addToast('success', title, message);
  }, [addToast]);

  const error = useCallback((title: string, message?: string) => {
    return addToast('error', title, message);
  }, [addToast]);

  const warning = useCallback((title: string, message?: string) => {
    return addToast('warning', title, message);
  }, [addToast]);

  const info = useCallback((title: string, message?: string) => {
    return addToast('info', title, message);
  }, [addToast]);

  return {
    toasts,
    addToast,
    removeToast,
    success,
    error,
    warning,
    info,
  };
}

/src/hooks/useWallet.ts:
/**
 * Wallet connection hook for VORTEX PROTOCOL
 * Manages wallet state, connection status, and address operations
 * Ready to integrate with Reown AppKit / Wagmi v3 / Coinbase Smart Wallet
 */

import { useState, useCallback } from 'react';
import { WalletState } from '../types';

const MOCK_ADDRESS = '0x742d35Cc6634C0532925a3b844Bc9e7595f8c2Ab';

export function useWallet() {
  const [wallet, setWallet] = useState<WalletState>({
    isConnected: false,
  });
  const [isConnecting, setIsConnecting] = useState(false);

  const connect = useCallback(async () => {
    setIsConnecting(true);
    // Simulate connection delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    setWallet({
      isConnected: true,
      address: MOCK_ADDRESS,
      ensName: 'vortex.eth',
      chainId: 'base',
    });
    setIsConnecting(false);
  }, []);

  const disconnect = useCallback(() => {
    setWallet({ isConnected: false });
  }, []);

  const formatAddress = useCallback((address: string) => {
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  }, []);

  return {
    wallet,
    isConnecting,
    connect,
    disconnect,
    formatAddress,
  };
}

