/**
 * Scan Page for VORTEX PROTOCOL
 * Chain selector, address input, scan results with tier classification
 * Allows selection of assets for consolidation
 */

import React, { useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { Search, Filter, ArrowRight, RefreshCw, CheckCircle2, AlertCircle, Sparkles, Eye, EyeOff } from 'lucide-react';
import { Button } from '../components/ui/Button';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '../components/ui/Card';
import { Input } from '../components/ui/Input';
import { Badge } from '../components/ui/Badge';
import { ChainSelector } from '../components/ChainChip';
import { AssetCard } from '../components/AssetCard';
import { TierBadge } from '../components/TierBadge';
import { SkeletonAssetCard } from '../components/ui/Skeleton';
import { EmptyState } from '../components/ui/EmptyState';
import { getAllChains } from '../constants/chains';
import { MOCK_SCAN_RESULTS, MOCK_ASSETS } from '../constants/mockData';
import { Asset, RiskTier, ScanResults } from '../types';
import { cn } from '../utils/cn';

interface ScanPageProps {
  walletAddress?: string;
  onShowToast: (type: 'success' | 'error' | 'warning' | 'info', title: string, message?: string) => void;
}

type FilterTab = 'all' | 'legit' | 'dust' | 'risk';

export function ScanPage({ walletAddress, onShowToast }: ScanPageProps) {
  const navigate = useNavigate();
  const chains = getAllChains();

  // State
  const [selectedChains, setSelectedChains] = useState<string[]>(['base', 'ethereum', 'arbitrum']);
  const [addressInput, setAddressInput] = useState(walletAddress || '');
  const [isScanning, setIsScanning] = useState(false);
  const [scanResults, setScanResults] = useState<ScanResults | null>(null);
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [activeFilter, setActiveFilter] = useState<FilterTab>('all');
  const [hideMicrodust, setHideMicrodust] = useState(true);

  const handleToggleChain = useCallback((chainId: string) => {
    setSelectedChains(prev =>
      prev.includes(chainId)
        ? prev.filter(id => id !== chainId)
        : [...prev, chainId]
    );
  }, []);

  const handleScan = useCallback(async () => {
    if (!addressInput.trim() && !walletAddress) {
      onShowToast('error', 'Address required', 'Please enter a wallet address or connect your wallet.');
      return;
    }
    if (selectedChains.length === 0) {
      onShowToast('error', 'Select chains', 'Please select at least one chain to scan.');
      return;
    }

    setIsScanning(true);
    setScanResults(null);
    setSelectedAssets([]);

    // Simulate scanning delay
    await new Promise(resolve => setTimeout(resolve, 2000));

    setScanResults(MOCK_SCAN_RESULTS);
    setIsScanning(false);
    onShowToast('success', 'Scan complete', `Found ${MOCK_SCAN_RESULTS.totalAssets} assets across ${selectedChains.length} chains.`);
  }, [addressInput, walletAddress, selectedChains, onShowToast]);

  const handleToggleAsset = useCallback((assetId: string) => {
    setSelectedAssets(prev =>
      prev.includes(assetId)
        ? prev.filter(id => id !== assetId)
        : [...prev, assetId]
    );
  }, []);

  const handleSelectAllDust = useCallback(() => {
    if (!scanResults) return;
    const dustAssetIds = scanResults.assets
      .filter(a => a.tier === 'DUST' || a.tier === 'MICRODUST')
      .map(a => a.id);
    setSelectedAssets(dustAssetIds);
  }, [scanResults]);

  const handleClearSelection = useCallback(() => {
    setSelectedAssets([]);
  }, []);

  const handleContinue = useCallback(() => {
    if (selectedAssets.length === 0) {
      onShowToast('warning', 'Select assets', 'Please select at least one asset to consolidate.');
      return;
    }
    navigate('/consolidate');
  }, [selectedAssets, navigate, onShowToast]);

  // Filter assets
  const filterAssets = useCallback((assets: Asset[]): Asset[] => {
    let filtered = assets;

    // Apply tier filter
    switch (activeFilter) {
      case 'legit':
        filtered = filtered.filter(a => a.tier === 'LEGIT');
        break;
      case 'dust':
        filtered = filtered.filter(a => a.tier === 'DUST' || a.tier === 'MICRODUST');
        break;
      case 'risk':
        filtered = filtered.filter(a => a.tier === 'RISK_SCAM');
        break;
    }

    // Hide microdust if enabled
    if (hideMicrodust && activeFilter !== 'dust') {
      filtered = filtered.filter(a => a.tier !== 'MICRODUST');
    }

    return filtered;
  }, [activeFilter, hideMicrodust]);

  const filteredAssets = scanResults ? filterAssets(scanResults.assets) : [];

  // Count by tier
  const tierCounts = scanResults ? {
    all: scanResults.assets.length,
    legit: scanResults.assets.filter(a => a.tier === 'LEGIT').length,
    dust: scanResults.assets.filter(a => a.tier === 'DUST' || a.tier === 'MICRODUST').length,
    risk: scanResults.assets.filter(a => a.tier === 'RISK_SCAM').length,
  } : { all: 0, legit: 0, dust: 0, risk: 0 };

  const selectedValue = selectedAssets.reduce((sum, id) => {
    const asset = scanResults?.assets.find(a => a.id === id);
    return sum + (asset?.valueUSD || 0);
  }, 0);

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Page Header */}
      <div className="mb-8">
        <h1 className="text-2xl sm:text-3xl font-bold text-foreground">Scan Portfolio</h1>
        <p className="mt-2 text-muted-foreground">
          Select chains and scan any wallet to discover dust and low-value assets.
        </p>
      </div>

      {/* Scan Configuration */}
      <Card className="mb-8">
        <CardContent className="space-y-6">
          {/* Chain Selector */}
          <ChainSelector
            selectedChains={selectedChains}
            onToggleChain={handleToggleChain}
            chains={chains}
            disabled={isScanning}
          />

          {/* Address Input */}
          <div className="space-y-2">
            <label className="text-sm font-medium text-foreground">Wallet Address</label>
            <div className="flex gap-3">
              <Input
                placeholder="0x... or ENS name"
                value={addressInput}
                onChange={(e) => setAddressInput(e.target.value)}
                leftIcon={<Search className="w-4 h-4" />}
                disabled={isScanning}
                className="flex-1"
              />
              <Button
                variant="primary"
                onClick={handleScan}
                isLoading={isScanning}
                leftIcon={isScanning ? undefined : <RefreshCw className="w-4 h-4" />}
                className="min-w-[140px]"
              >
                {isScanning ? 'Scanning...' : 'Scan'}
              </Button>
            </div>
            {walletAddress && !addressInput && (
              <p className="text-sm text-muted-foreground">
                Using connected wallet: {walletAddress.slice(0, 6)}...{walletAddress.slice(-4)}
              </p>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Scanning State */}
      <AnimatePresence mode="wait">
        {isScanning && (
          <motion.div
            key="scanning"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-4"
          >
            <Card className="text-center py-12">
              <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 mb-4">
                <RefreshCw className="w-8 h-8 text-primary animate-spin" />
              </div>
              <h3 className="text-lg font-semibold text-foreground">Scanning {selectedChains.length} chains...</h3>
              <p className="text-muted-foreground mt-2">This may take a moment.</p>
            </Card>
            <div className="space-y-3">
              {[1, 2, 3].map(i => (
                <SkeletonAssetCard key={i} />
              ))}
            </div>
          </motion.div>
        )}

        {/* Results */}
        {!isScanning && scanResults && (
          <motion.div
            key="results"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6"
          >
            {/* Summary Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <Card variant="glass" className="text-center py-4">
                <p className="text-2xl font-bold text-foreground">
                  ${scanResults.totalValueUSD.toLocaleString()}
                </p>
                <p className="text-xs text-muted-foreground mt-1">Total Value</p>
              </Card>
              <Card variant="glass" className="text-center py-4">
                <p className="text-2xl font-bold text-foreground">{scanResults.totalAssets}</p>
                <p className="text-xs text-muted-foreground mt-1">Assets Found</p>
              </Card>
              <Card variant="glass" className="text-center py-4">
                <p className="text-2xl font-bold text-amber-500">
                  ${scanResults.dustValueUSD.toFixed(2)}
