/**
 * Stepper component for VORTEX PROTOCOL
 * Visual progress indicator for consolidation flow
 * Steps: Simulate → Sponsor Gas → Bundle → Confirm
 */

import React from 'react';
import { motion } from 'framer-motion';
import { Check, Loader2, Circle, AlertCircle } from 'lucide-react';
import { ConsolidationStep } from '../types';
import { cn } from '../utils/cn';

interface StepperProps {
  steps: ConsolidationStep[];
  currentStep: number;
}

const statusIcons = {
  pending: Circle,
  'in-progress': Loader2,
  complete: Check,
  error: AlertCircle,
};

const statusStyles = {
  pending: 'bg-muted text-muted-foreground border-border',
  'in-progress': 'bg-primary/10 text-primary border-primary animate-pulse',
  complete: 'bg-accent text-accent-foreground border-accent',
  error: 'bg-destructive/10 text-destructive border-destructive',
};

export function Stepper({ steps, currentStep }: StepperProps) {
  return (
    <div className="space-y-4">
      {steps.map((step, index) => {
        const Icon = statusIcons[step.status];
        const isActive = index === currentStep;
        const isPast = index < currentStep;

        return (
          <motion.div
            key={step.id}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: index * 0.1 }}
            className={cn(
              'flex items-start gap-4 p-4 rounded-xl border transition-all duration-300',
              isActive ? 'bg-card border-primary/50 shadow-sm' : 'bg-muted/30 border-transparent'
            )}
          >
            <div
              className={cn(
                'flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center border-2',
                statusStyles[step.status]
              )}
            >
              <Icon className={cn('w-5 h-5', step.status === 'in-progress' && 'animate-spin')} />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <h4 className={cn(
                  'font-semibold',
                  isActive ? 'text-foreground' : isPast ? 'text-muted-foreground' : 'text-muted-foreground'
                )}>
                  {step.name}
                </h4>
                {step.status === 'complete' && (
                  <span className="text-xs text-accent font-medium">Complete</span>
                )}
                {step.status === 'error' && (
                  <span className="text-xs text-destructive font-medium">Failed</span>
                )}
              </div>
              <p className="text-sm text-muted-foreground mt-1">{step.description}</p>
            </div>
            <div className="text-sm text-muted-foreground">
              {index + 1}/{steps.length}
            </div>
          </motion.div>
        );
      })}
    </div>
  );
}

export function StepperMini({ steps, currentStep }: StepperProps) {
  return (
    <div className="flex items-center gap-2">
      {steps.map((step, index) => {
        const isComplete = step.status === 'complete';
        const isActive = step.status === 'in-progress';

        return (
          <React.Fragment key={step.id}>
            <div
              className={cn(
                'w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all',
                isComplete && 'bg-accent text-accent-foreground',
                isActive && 'bg-primary text-primary-foreground',
                !isComplete && !isActive && 'bg-muted text-muted-foreground'
              )}
            >
              {isComplete ? <Check className="w-4 h-4" /> : index + 1}
            </div>
            {index < steps.length - 1 && (
              <div
                className={cn(
                  'h-0.5 w-8 transition-all',
                  isComplete ? 'bg-accent' : 'bg-muted'
                )}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}

export default Stepper;

