                <CardTitle>Auto-Hide Microdust</CardTitle>
                <CardDescription>Automatically hide assets worth less than $0.10</CardDescription>
              </div>
              <button
                onClick={() => setSettings(s => ({ ...s, autoHideMicrodust: !s.autoHideMicrodust }))}
                className={cn(
                  'relative w-14 h-8 rounded-full transition-colors',
                  settings.autoHideMicrodust ? 'bg-primary' : 'bg-muted'
                )}
                role="switch"
                aria-checked={settings.autoHideMicrodust}
              >
                <motion.span
                  animate={{ x: settings.autoHideMicrodust ? 24 : 4 }}
                  className="absolute top-1 w-6 h-6 rounded-full bg-white shadow-sm"
                />
              </button>
            </div>
          </CardHeader>
        </Card>

        {/* Notifications */}
        <Card>
          <CardHeader>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                {settings.notificationsEnabled ? (
                  <Bell className="w-5 h-5 text-muted-foreground" />
                ) : (
                  <BellOff className="w-5 h-5 text-muted-foreground" />
                )}
              </div>
              <div className="flex-1">
                <CardTitle>Notifications</CardTitle>
                <CardDescription>Receive alerts for completed transactions and new dust detected</CardDescription>
              </div>
              <button
                onClick={() => setSettings(s => ({ ...s, notificationsEnabled: !s.notificationsEnabled }))}
                className={cn(
                  'relative w-14 h-8 rounded-full transition-colors',
                  settings.notificationsEnabled ? 'bg-primary' : 'bg-muted'
                )}
                role="switch"
                aria-checked={settings.notificationsEnabled}
              >
                <motion.span
                  animate={{ x: settings.notificationsEnabled ? 24 : 4 }}
                  className="absolute top-1 w-6 h-6 rounded-full bg-white shadow-sm"
                />
              </button>
            </div>
          </CardHeader>
        </Card>

        {/* Actions */}
        <div className="flex gap-4 pt-4">
          <Button
            variant="ghost"
            onClick={handleReset}
            leftIcon={<RefreshCw className="w-4 h-4" />}
          >
            Reset to Defaults
          </Button>
          <Button
            variant="primary"
            className="flex-1"
            onClick={handleSave}
            isLoading={isSaving}
            leftIcon={isSaving ? undefined : <Save className="w-4 h-4" />}
          >
            {isSaving ? 'Saving...' : 'Save Changes'}
          </Button>
        </div>
      </div>
    </div>
  );
}

export default SettingsPage;

