                      className="flex items-center justify-between px-3 py-3 rounded-xl hover:bg-muted transition-colors min-h-[44px]"
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      <span className="font-medium">{link.label}</span>
                      <ExternalLink className="w-4 h-4 text-muted-foreground" />
                    </a>
                  ) : (
                    <Link
                      key={link.label}
                      to={link.href}
                      className="flex items-center px-3 py-3 rounded-xl hover:bg-muted transition-colors min-h-[44px] font-medium"
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      {link.label}
                    </Link>
                  )
                ))}
              </nav>

              {/* Wallet Connect - Mobile */}
              <div className="pt-2 border-t border-border">
                <WalletConnect
                  isConnected={wallet.isConnected}
                  address={wallet.address}
                  ensName={wallet.ensName}
                  onConnect={onConnect}
                  onDisconnect={onDisconnect}
                  isConnecting={isConnecting}
                />
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

export default Header;

